     1	<script lang="ts">
     2	import {
     3		createMutation,
     4		createQuery,
     5		useQueryClient,
     6	} from "@tanstack/svelte-query";
     7	import {
     8		membersAnalyticsQueryKey,
     9		membersListQueryKey,
    10		membersMeQueryKey,
    11		membersShowQueryKey,
    12		membershipBillingPortalMutation,
    13		membershipReactivateMutation,
    14		membershipReactivationPreviewAmountsOptions,
    15		membershipReactivationPreviewOptions,
    16		type MembershipReactivateAnnualFeeMode,
    17	} from "@dhc/api-client";
    18	import { page } from "$app/state";
    19	import { toast } from "svelte-sonner";
    20	import ReactivateMembershipModal from "./reactivate-membership-modal.svelte";
    21	
    22	/**
    23	 * Self-contained reactivation interaction (ALE-252): fetches the saved SEPA
    24	 * method preview while open, submits the reactivation through the generated
    25	 * mutation options, reports pending/succeeded/declined outcomes as toasts,
    26	 * and reconciles the standard membership queries on success.
    27	 */
    28	let {
    29		/** Member to reactivate; falsy unmounts nothing but disables queries. */
    30		memberId,
    31		open = $bindable(false),
    32		/** Extra caller-side reconciliation (e.g. SvelteKit load dependencies). */
    33		onSettled,
    34	}: {
    35		memberId: string;
    36		open?: boolean;
    37		onSettled?: () => Promise<void> | void;
    38	} = $props();
    39	
    40	const queryClient = useQueryClient();
    41	
    42	// Saved SEPA method shown BEFORE any charge; fetched lazily through the
    43	// generated preview query options while the dialog is open.
    44	const reactivationPreview = createQuery(() => ({
    45		...membershipReactivationPreviewOptions({
    46			path: { memberId },
    47		}),
    48		enabled: open && memberId !== "",
    49	}));
    50	
    51	// The selected start date and annual fee mode are owned by the modal (date
    52	// picker + radio group) and reported up through onSelectionChange so the
    53	// amounts query can key off both (ALE-254, ALE-253).
    54	let previewStartDate = $state<string | null>(null);
    55	let previewAnnualFeeMode =
    56		$state<MembershipReactivateAnnualFeeMode>("prorated_now");
    57	
    58	// Stripe-computed amounts for the chosen selection, fetched only once a
    59	// saved method exists (otherwise the operator gets the billing-portal
    60	// fallback instead). Keyed by startDate AND annualFeeMode, so changing
    61	// either refetches. Failure degrades gracefully: the modal hides amounts
    62	// and keeps the form usable — this query failing must never block a valid
    63	// charge.
    64	const reactivationAmounts = createQuery(() => ({
    65		...membershipReactivationPreviewAmountsOptions({
    66			path: { memberId },
    67			query: {
    68				startDate: previewStartDate ?? "",
    69				annualFeeMode: previewAnnualFeeMode,
    70			},
    71		}),
    72		enabled:
    73			open &&
    74			memberId !== "" &&
    75			previewStartDate !== null &&
    76			Boolean(reactivationPreview.data?.data.savedPaymentMethod),
    77	}));
    78	
    79	// Submission error kept inside the modal so the operator can retry without
    80	// losing context; `noSavedMethod` switches it to the billing-portal fallback.
    81	let submitError = $state<{
    82		detail: string;
    83		noSavedMethod: boolean;
    84	} | null>(null);
    85	
    86	function isOwnProfile(): boolean {
    87		return page.data.session?.principal?.id === memberId;
    88	}
    89	
    90	async function reconcile() {
    91		await Promise.all([
    92			queryClient.invalidateQueries({ queryKey: membersListQueryKey() }),
    93			queryClient.invalidateQueries({
    94				queryKey: membersShowQueryKey({ path: { memberId } }),
    95			}),
    96			queryClient.invalidateQueries({ queryKey: membersAnalyticsQueryKey() }),
    97			isOwnProfile()
    98				? queryClient.invalidateQueries({ queryKey: membersMeQueryKey() })
    99				: Promise.resolve(),
   100		]);
   101	}
   102	
   103	const reactivateMutation = createMutation(() => ({
   104		...membershipReactivateMutation(),
   105		onSuccess: async ({ data: result }) => {
   106			open = false;
   107			submitError = null;
   108			if (result.paymentState === "succeeded") {
   109				toast.success("Membership reactivated.", { position: "top-right" });
   110			} else if (result.paymentState === "terminal") {
   111				toast.error(
   112					"Reactivation submitted, but the bank declined the charge. Use the billing portal to sort out payment.",
   113					{ position: "top-right", duration: 10000 },
   114				);
   115			} else if (
   116				result.paymentState === "pending" ||
   117				result.paymentState === "needs_action"
   118			) {
   119				toast.info(
   120					"Awaiting bank confirmation. SEPA direct debits usually settle within a few business days.",
   121					{ position: "top-right", duration: 10000 },
   122				);
   123			}
   124			await reconcile();
   125			await onSettled?.();
   126		},
   127		onError: (error) => {
   128			submitError = {
   129				detail: error.errors?.detail ?? "Failed to reactivate membership",
   130				noSavedMethod: error.errors?.code === "no_saved_payment_method",
   131			};
   132		},
   133	}));
   134	
   135	// Manual fallback when the member has no usable saved method (ALE-252):
   136	// the operator opens the Stripe-hosted portal for the member.
   137	const billingPortalMutation = createMutation(() => ({
   138		...membershipBillingPortalMutation(),
   139		onSuccess: (response) => {
   140			window.open(response.data.url, "_blank", "noopener,noreferrer");
   141		},
   142		onError: (error) => {
   143			toast.error(error.errors?.detail ?? "Failed to open billing portal");
   144		},
   145	}));
   146	</script>
   147	
   148	<ReactivateMembershipModal
   149		bind:open
   150		isPending={reactivateMutation.isPending}
   151		isLoadingPreview={reactivationPreview.isPending}
   152		savedPaymentMethod={reactivationPreview.data?.data.savedPaymentMethod ??
   153			undefined}
   154		membershipCoverage={reactivationPreview.data?.data.membershipCoverage}
   155		amounts={reactivationAmounts.data?.data ?? null}
   156		isLoadingAmounts={reactivationAmounts.isFetching}
   157		errorDetail={submitError?.detail ?? null}
   158		paymentMethodUnavailable={submitError?.noSavedMethod ?? false}
   159		onOpenBillingPortal={() =>
   160			billingPortalMutation.mutate({
   161				path: { memberId },
   162				body: { returnUrl: window.location.href },
   163			})}
   164		onSelectionChange={({ startDate, annualFeeMode }) => {
   165			previewStartDate = startDate;
   166			previewAnnualFeeMode = annualFeeMode;
   167		}}
   168		onConfirm={({ startDate, annualFeeMode }) => {
   169			submitError = null;
   170			reactivateMutation.mutate({
   171				path: { memberId },
   172				body: { startDate, annualFeeMode },
   173			});
   174		}}
   175	/>
     1	<script lang="ts">
     2	import { Button } from "#lib/components/ui/button/index.js";
     3	import * as Dialog from "#lib/components/ui/dialog/index.js";
     4	import { Label } from "#lib/components/ui/label/index.js";
     5	import * as Alert from "#lib/components/ui/alert/index.js";
     6	import { Badge } from "#lib/components/ui/badge/index.js";
     7	import * as RadioGroup from "#lib/components/ui/radio-group/index.js";
     8	import DatePicker from "#lib/components/ui/date-picker.svelte";
     9	import LoaderCircle from "#lib/components/ui/loader-circle.svelte";
    10	import CreditCard from "@lucide/svelte/icons/credit-card";
    11	import ExternalLink from "@lucide/svelte/icons/external-link";
    12	import TriangleAlert from "@lucide/svelte/icons/triangle-alert";
    13	import type { DateValue } from "@internationalized/date";
    14	import { civilIsoDate, formatCivilDate } from "#lib/club-calendar.js";
    15	import {
    16		isFutureStart,
    17		reactivationStartWindow,
    18	} from "#lib/membership/reactivation-start-window.js";
    19	import Dinero from "dinero.js";
    20	import { untrack } from "svelte";
    21	import type {
    22		MembershipReactivateAnnualFeeMode,
    23		MembershipReactivationPreviewAmountsResponse,
    24		MembershipReactivationPreviewResponse,
    25	} from "@dhc/api-client";
    26	
    27	// Mirrors the savedPaymentMethod summary projected by
    28	// GET /members/{memberId}/membership/reactivation-preview.
    29	type SavedPaymentMethod = NonNullable<
    30		MembershipReactivationPreviewResponse["data"]["savedPaymentMethod"]
    31	>;
    32	
    33	// Mirrors the Stripe-computed amounts projected by
    34	// GET /members/{memberId}/membership/reactivation-preview/amounts (ALE-254).
    35	type ReactivationAmounts = MembershipReactivationPreviewAmountsResponse["data"];
    36	type MembershipCoverage =
    37		MembershipReactivationPreviewResponse["data"]["membershipCoverage"];
    38	
    39	// ALE-253: how the annual membership fee begins — charged prorated now, or
    40	// deferred to next January's anchor behind a free trial.
    41	type AnnualFeeMode = MembershipReactivateAnnualFeeMode;
    42	
    43	function isAnnualFeeMode(value: string): value is AnnualFeeMode {
    44		return value === "prorated_now" || value === "deferred_next_year";
    45	}
    46	
    47	type Props = {
    48		open: boolean;
    49		onConfirm: ({
    50			startDate,
    51			annualFeeMode,
    52		}: {
    53			startDate: string;
    54			annualFeeMode: AnnualFeeMode;
    55		}) => void;
    56		isPending: boolean;
    57		savedPaymentMethod?: SavedPaymentMethod | null;
    58		membershipCoverage?: MembershipCoverage;
    59		isLoadingPreview?: boolean;
    60		/** The saved-method preview itself failed to load (e.g. Stripe 502). */
    61		previewError?: boolean;
    62		errorDetail?: string | null;
    63		paymentMethodUnavailable?: boolean;
    64		onOpenBillingPortal?: () => void;
    65		/** Stripe-computed reactivation amounts; hidden on failure. */
    66		amounts?: ReactivationAmounts | null;
    67		isLoadingAmounts?: boolean;
    68		/** Optional initial selection when the caller already has a requested date. */
    69		initialStartDate?: DateValue;
    70		/** Reports start date + annual fee mode so the container can fetch amounts. */
    71		onSelectionChange?: (selection: {
    72			startDate: string;
    73			annualFeeMode: AnnualFeeMode;
    74		}) => void;
    75	};
    76	
    77	let {
    78		open = $bindable(false),
    79		onConfirm,
    80		isPending,
    81		savedPaymentMethod,
    82		membershipCoverage = { monthly: "lapsed", annual: "lapsed" },
    83		isLoadingPreview = false,
    84		previewError = false,
    85		errorDetail = null,
    86		paymentMethodUnavailable = false,
    87		onOpenBillingPortal,
    88		amounts = null,
    89		isLoadingAmounts = false,
    90		initialStartDate,
    91		onSelectionChange,
    92	}: Props = $props();
    93	
    94	// Phoenix accepts a start date from its (UTC) today up to 366 days ahead;
    95	// the window module reconciles that with Dublin's today. Read once per mount:
    96	// the page mounts the modal inside {#if} only while open.
    97	const { earliest: minDate, latest: maxDate } = reactivationStartWindow();
    98	let selectedDate = $state<DateValue>(
    99		untrack(() => initialStartDate ?? minDate),
   100	);
   101	// ALE-253: default keeps the initial-release semantics (annual charged
   102	// prorated for the remainder of this year).
   103	let annualFeeMode = $state<AnnualFeeMode>("prorated_now");
   104	
   105	const startDateIso = $derived(civilIsoDate(selectedDate));
   106	const deferredAnnual = $derived(annualFeeMode === "deferred_next_year");
   107	const monthlyActive = $derived(membershipCoverage.monthly === "active");
   108	const annualActive = $derived(membershipCoverage.annual === "active");
   109	const completeCoverage = $derived(monthlyActive && annualActive);
   110	const futureStart = $derived(isFutureStart(startDateIso));
   111	const formattedStartDate = $derived(formatCivilDate(startDateIso));
   112	// Distinguishes "Stripe says there is nothing to charge" (fallback applies)
   113	// from "the preview lookup itself failed" (plain error, retry by reopening).
   114	const methodUnavailable = $derived(
   115		paymentMethodUnavailable ||
   116			(!isLoadingPreview &&
   117				!previewError &&
   118				(savedPaymentMethod ?? null) === null),
   119	);
   120	
   121	function handleConfirm(event: Event) {
   122		event.preventDefault();
   123		event.stopPropagation();
   124		if (!selectedDate || isPending || methodUnavailable || completeCoverage)
   125			return;
   126		onConfirm({ startDate: startDateIso, annualFeeMode });
   127	}
   128	
   129	// The container fetches Stripe-computed amounts for the selection; the query
   130	// key changes with either field, so this fires on mount and on every change.
   131	$effect(() => {
   132		onSelectionChange?.({ startDate: startDateIso, annualFeeMode });
   133	});
   134	
   135	function handleModeChange(value: string) {
   136		if (isAnnualFeeMode(value)) {
   137			annualFeeMode = value;
   138		}
   139	}
   140	
   141	function formatMoney(money: ReactivationAmounts["dueToday"]) {
   142		// SAFETY: dinero.js narrows currency to an ISO-4217 literal union while
   143		// the API type keeps `string`; the server pins the currency to EUR, so
   144		// every value reaching here satisfies the narrower union.
   145		return Dinero(money as Dinero.DineroObject).toFormat();
   146	}
   147	
   148	function handleDateChange(date: DateValue | undefined) {
   149		if (date) selectedDate = date;
   150	}
   151	</script>
   152	
   153	<Dialog.Root bind:open>
   154		<!-- ALE-253 grew this dialog taller than some viewports: keep the whole
   155		     content scrollable so the confirm footer stays reachable. -->
   156		<Dialog.Content class="max-h-[85vh] overflow-y-auto">
   157			<Dialog.Header>
   158				<Dialog.Title>Reactivate membership</Dialog.Title>
   159				<Dialog.Description>
   160					{#if completeCoverage}
   161						Stripe already reports both membership subscriptions as active.
   162						Nothing will be recreated or charged.
   163					{:else if monthlyActive}
   164						Keeps the active monthly subscription unchanged and reactivates only
   165						the annual subscription using the member’s saved SEPA payment method.
   166					{:else if annualActive}
   167						Keeps the active annual subscription unchanged and reactivates only
   168						the monthly subscription using the member’s saved SEPA payment method.
   169					{:else}
   170						Starts new monthly and annual membership subscriptions, charged
   171						automatically to the member’s saved SEPA payment method. They don’t
   172						need to enter their bank details again.
   173					{/if}
   174				</Dialog.Description>
   175			</Dialog.Header>
   176	
   177			{#if isLoadingPreview}
   178				<div class="flex items-center gap-2 text-sm text-muted-foreground">
   179					<LoaderCircle class="size-4 animate-spin" />
   180					Checking saved payment method…
   181				</div>
   182			{:else if previewError}
   183				<Alert.Root variant="destructive">
   184					<TriangleAlert />
   185					<Alert.Title>Could not check the saved payment method</Alert.Title>
   186					<Alert.Description>
   187						The saved payment method could not be loaded. Close this dialog and
   188						try again; nothing has been charged.
   189					</Alert.Description>
   190				</Alert.Root>
   191			{:else if methodUnavailable}
   192				<Alert.Root>
   193					<TriangleAlert />
   194					<Alert.Title>No saved payment method</Alert.Title>
   195					<Alert.Description>
   196						This member has no saved SEPA payment details to charge, so the
   197						subscriptions can’t be started here. Open the Stripe billing portal
   198						instead: the member enters their bank details and restarts the
   199						subscription themselves.
   200					</Alert.Description>
   201				</Alert.Root>
   202				{#if onOpenBillingPortal}
   203					<Button variant="outline" class="w-full" onclick={onOpenBillingPortal}>
   204						Open billing portal
   205						<ExternalLink class="size-4" aria-hidden="true" />
   206					</Button>
   207				{/if}
   208			{:else if savedPaymentMethod}
   209				<div class="space-y-4">
   210					<div class="grid gap-2 sm:grid-cols-2" aria-label="Membership coverage">
   211						<div
   212							class="rounded-xl border border-border/80 p-3"
   213							data-testid="monthly-coverage"
   214						>
   215							<p class="text-sm font-medium">Monthly subscription</p>
   216							<p class="mt-1 text-xs text-muted-foreground">
   217								{monthlyActive
   218									? "Already active, kept unchanged"
   219									: "Will be reactivated"}
   220							</p>
   221						</div>
   222						<div
   223							class="rounded-xl border border-border/80 p-3"
   224							data-testid="annual-coverage"
   225						>
   226							<p class="text-sm font-medium">Annual subscription</p>
   227							<p class="mt-1 text-xs text-muted-foreground">
   228								{annualActive
   229									? "Already active, kept unchanged"
   230									: "Will be reactivated"}
   231							</p>
   232						</div>
   233					</div>
   234	
   235					<div
   236						class="flex items-center gap-3 rounded-xl border border-border/80 bg-muted/40 p-3"
   237						data-slot="saved-payment-method"
   238					>
   239						<div
   240							class="grid size-10 shrink-0 place-items-center rounded-full bg-primary/10 text-primary"
   241						>
   242							<CreditCard class="size-5" aria-hidden="true" />
   243						</div>
   244						<div class="min-w-0 flex-1">
   245							<p class="text-sm font-semibold">Saved SEPA Direct Debit</p>
   246							<p class="mt-0.5 text-sm text-muted-foreground">
   247								Ending in {savedPaymentMethod.last4}
   248							</p>
   249						</div>
   250						{#if savedPaymentMethod.country || savedPaymentMethod.bankCode}
   251							<Badge variant="secondary">
   252								{[savedPaymentMethod.country, savedPaymentMethod.bankCode]
   253									.filter(Boolean)
   254									.join(" · ")}
   255							</Badge>
   256						{/if}
   257					</div>
   258	
   259					<div class="space-y-2">
   260						<Label for="reactivation-start-date">Start date</Label>
   261						<DatePicker
   262							id="reactivation-start-date"
   263							name="startDate"
   264							value={selectedDate}
   265							minValue={minDate}
   266							maxValue={maxDate}
   267							onValueChange={handleDateChange}
   268						/>
   269						<p class="text-xs leading-4 text-muted-foreground">
   270							Billing starts on this date.
   271							{#if !monthlyActive}
   272								The first monthly charge is prorated from this date to the first
   273								of the following month, then full months bill from there.
   274							{/if}
   275							{#if !annualActive}
   276								{deferredAnnual
   277									? "The annual fee isn’t charged today; annual billing begins next January."
   278									: "The annual fee is charged prorated for the rest of this year."}
   279							{/if}
   280							Allowed window: {formatCivilDate(minDate.toString())} to {formatCivilDate(
   281								maxDate.toString(),
   282							)}.
   283						</p>
   284					</div>
   285	
   286					{#if !annualActive}
   287						<fieldset class="space-y-2">
   288							<legend class="text-sm font-medium">Annual fee</legend>
   289							<RadioGroup.Root
   290								name="annualFeeMode"
   291								class="grid gap-2"
   292								value={annualFeeMode}
   293								onValueChange={handleModeChange}
   294							>
   295								<Label
   296									for="annual-fee-prorated-now"
   297									class="flex min-h-12 cursor-pointer items-start gap-3 rounded-xl border border-border/80 p-3 transition-colors hover:bg-muted/50 has-[[data-state=checked]]:border-primary has-[[data-state=checked]]:bg-primary/5"
   298								>
   299									<RadioGroup.Item
   300										value="prorated_now"
   301										id="annual-fee-prorated-now"
   302										class="mt-0.5"
   303									/>
   304									<span>
   305										<span class="block font-medium">Charge now, prorated</span>
   306										<span
   307											class="mt-0.5 block text-sm font-normal text-muted-foreground"
   308										>
   309											The annual fee is charged prorated for the rest of this
   310											year, then renews each January.
   311										</span>
   312									</span>
   313								</Label>
   314								<Label
   315									for="annual-fee-deferred"
   316									class="flex min-h-12 cursor-pointer items-start gap-3 rounded-xl border border-border/80 p-3 transition-colors hover:bg-muted/50 has-[[data-state=checked]]:border-primary has-[[data-state=checked]]:bg-primary/5"
   317								>
   318									<RadioGroup.Item
   319										value="deferred_next_year"
   320										id="annual-fee-deferred"
   321										class="mt-0.5"
   322									/>
   323									<span>
   324										<span class="block font-medium">Defer until next January</span
   325										>
   326										<span
   327											class="mt-0.5 block text-sm font-normal text-muted-foreground"
   328										>
   329											Nothing is charged today. Annual billing begins next
   330											January.
   331										</span>
   332									</span>
   333								</Label>
   334							</RadioGroup.Root>
   335						</fieldset>
   336					{/if}
   337	
   338					{#if amounts || isLoadingAmounts}
   339						<div
   340							class="rounded-xl border border-border/80 bg-muted/40 p-3"
   341							data-slot="reactivation-amounts"
   342							data-testid="reactivation-amounts"
   343						>
   344							{#if !amounts}
   345								<p
   346									class="flex items-center gap-2 text-sm text-muted-foreground"
   347									role="status"
   348								>
   349									<LoaderCircle class="size-4 animate-spin" />
   350									Calculating what this reactivation will charge…
   351								</p>
   352							{:else}
   353								<div class="space-y-4">
   354									<div class="flex items-start justify-between gap-4">
   355										<div>
   356											<p class="font-semibold">Due today</p>
   357											{#if monthlyActive}
   358												<p class="mt-1 text-xs leading-5 text-muted-foreground">
   359													{formatMoney(amounts.proratedAnnualPrice)} for this year
   360												</p>
   361											{:else if annualActive}
   362												<p class="mt-1 text-xs leading-5 text-muted-foreground">
   363													{futureStart
   364														? "Monthly billing begins on the selected start date"
   365														: `${formatMoney(amounts.proratedMonthlyPrice)} for this month`}
   366												</p>
   367											{:else if futureStart}
   368												<p class="mt-1 text-xs leading-5 text-muted-foreground">
   369													{formatMoney(amounts.proratedAnnualPrice)} for this year
   370												</p>
   371											{:else}
   372												<p class="mt-1 text-xs leading-5 text-muted-foreground">
   373													{formatMoney(amounts.proratedMonthlyPrice)} for this month
   374													+
   375													{formatMoney(amounts.proratedAnnualPrice)} for this year
   376												</p>
   377											{/if}
   378										</div>
   379										<span class="text-lg font-bold"
   380											>{formatMoney(amounts.dueToday)}</span
