     1	import type {
     2		TrainingAnnouncement,
     3		TrainingAnnouncementCopyRequest,
     4		TrainingAnnouncementCreateRequest,
     5		TrainingAnnouncementScheduleRequest,
     6		TrainingAnnouncementWarning,
     7	} from "@dhc/api-client";
     8	import { assign, fromPromise, setup, type SnapshotFrom } from "xstate";
     9	import { apiProblem, type ApiFieldMessages } from "#lib/api-error.js";
    10	import {
    11		copyRequest,
    12		createRequest,
    13		scheduleChanged,
    14		scheduleRequest,
    15		type AnnouncementDraft,
    16		type AnnouncementSave,
    17	} from "./announcement";
    18	
    19	/**
    20	 * Component-scoped save protocol of the Training Announcement sheet (ALE-448).
    21	 *
    22	 * Creating is one write. Editing is two separate, non-atomic writes the API
    23	 * models apart: the schedule (only when it actually changed, since it swaps
    24	 * the pending job and may return advisory warnings), then the copy. Their
    25	 * order is the safety rule — an elapsed slot is refused before any copy is
    26	 * written, so a schedule refusal never reaches the copy stage.
    27	 *
    28	 * A copy failure after a schedule write lands in `edit.copyFailed`: the
    29	 * schedule stays applied (nothing is rolled back) and `baseline` is the row
    30	 * Phoenix returned for it, so the next save re-runs the schedule stage only if
    31	 * the draft's schedule differs from what already landed.
    32	 *
    33	 * TanStack Query stays the server-state owner: the injected actors are its
    34	 * mutations, which own optimistic rows, rollback and list invalidation. The
    35	 * machine never caches a row for display. Instantiate it per sheet with
    36	 * `useMachine`; stopping it (closing the sheet) discards late results.
    37	 */
    38	
    39	export type AnnouncementSaveStage = "create" | "schedule" | "copy";
    40	
    41	/** Why the last save stopped, scoped to the request that refused it. */
    42	export type AnnouncementSaveProblem = {
    43		stage: AnnouncementSaveStage;
    44		/** Phoenix's problem detail, or `undefined` when the failure had none. */
    45		detail: string | undefined;
    46		fields: ApiFieldMessages[];
    47	};
    48	
    49	export type AnnouncementSaveInput = {
    50		/** `null` creates a new announcement; an existing row edits it. */
    51		announcement: TrainingAnnouncement | null;
    52	};
    53	
    54	export type AnnouncementSaveContext = {
    55		/**
    56		 * The authoritative row the next save compares its draft against: the row
    57		 * the sheet opened, then the row a successful schedule write returned.
    58		 */
    59		baseline: TrainingAnnouncement | null;
    60		/** The draft being saved, as it was when the save started. */
    61		draft: AnnouncementDraft | null;
    62		/** Warnings from the schedule write this sheet already committed. */
    63		warnings: TrainingAnnouncementWarning[];
    64		/**
    65		 * A schedule write committed in this sheet. It is never rolled back, so a
    66		 * later copy failure leaves the announcement half-edited, honestly.
    67		 */
    68		scheduleApplied: boolean;
    69		problem: AnnouncementSaveProblem | null;
    70	};
    71	
    72	export type AnnouncementSaveEvent =
    73		| { type: "SAVE"; draft: AnnouncementDraft }
    74		| { type: "CLOSE" };
    75	
    76	/** Implementations a host component provides through `announcementSaveMachine.provide`. */
    77	export type AnnouncementSaveImplementations = {
    78		create: (input: {
    79			body: TrainingAnnouncementCreateRequest;
    80		}) => Promise<AnnouncementSave>;
    81		updateSchedule: (input: {
    82			id: string;
    83			body: TrainingAnnouncementScheduleRequest;
    84		}) => Promise<AnnouncementSave>;
    85		updateCopy: (input: {
    86			id: string;
    87			body: TrainingAnnouncementCopyRequest;
    88		}) => Promise<TrainingAnnouncement>;
    89		/** A save committed: report it (warnings included) to the owner. */
    90		saved: (save: AnnouncementSave) => void;
    91		/** The workflow is over (saved or dismissed): close the sheet. */
    92		close: () => void;
    93	};
    94	
    95	function problemOf(
    96		cause: unknown,
    97		stage: AnnouncementSaveStage,
    98	): AnnouncementSaveProblem {
    99		const problem = apiProblem(cause);
   100		return { stage, detail: problem?.detail, fields: problem?.fields ?? [] };
   101	}
   102	
   103	function unprovided(name: string) {
   104		return async (): Promise<never> => {
   105			throw new Error(`${name} must be provided by the host`);
   106		};
   107	}
   108	
   109	function requireBaseline(context: AnnouncementSaveContext) {
   110		if (!context.baseline || !context.draft)
   111			throw new Error("an edit stage needs the announcement and its draft");
   112		return { id: context.baseline.id, draft: context.draft };
   113	}
   114	
   115	/**
   116	 * How every resting edit state routes a save: through the schedule stage only
   117	 * when the draft moved off the authoritative schedule, otherwise straight to
   118	 * the copy stage.
   119	 */
   120	const editSave = [
   121		{
   122			guard: "scheduleChanged",
   123			target: "savingSchedule",
   124			actions: "startSave",
   125		},
   126		{ target: "savingCopy", actions: "startSave" },
   127	] as const;
   128	
   129	export const announcementSaveMachine = setup({
   130		// SAFETY: XState's `setup({ types })` reads only the *types* of these
   131		// placeholders; the empty objects are never used as values.
   132		types: {
   133			context: {} as AnnouncementSaveContext,
   134			events: {} as AnnouncementSaveEvent,
   135			input: {} as AnnouncementSaveInput,
   136		},
   137		actors: {
   138			create: fromPromise<
   139				AnnouncementSave,
   140				{ body: TrainingAnnouncementCreateRequest }
   141			>(unprovided("create")),
   142			updateSchedule: fromPromise<
   143				AnnouncementSave,
   144				{ id: string; body: TrainingAnnouncementScheduleRequest }
   145			>(unprovided("updateSchedule")),
   146			updateCopy: fromPromise<
   147				TrainingAnnouncement,
   148				{ id: string; body: TrainingAnnouncementCopyRequest }
   149			>(unprovided("updateCopy")),
   150		},
   151		actions: {
   152			startSave: assign({
   153				draft: ({ event }) => (event.type === "SAVE" ? event.draft : null),
   154				problem: null,
   155			}),
   156			saved: (_, _save: AnnouncementSave) => {},
   157			close: () => {},
   158		},
   159		guards: {
   160			creating: ({ context }) => context.baseline === null,
   161			scheduleChanged: ({ context, event }) =>
   162				event.type === "SAVE" &&
   163				context.baseline !== null &&
   164				scheduleChanged(event.draft, context.baseline),
   165		},
   166	}).createMachine({
   167		id: "announcementSave",
   168		context: ({ input }) => ({
   169			baseline: input.announcement,
   170			draft: null,
   171			warnings: [],
   172			scheduleApplied: false,
   173			problem: null,
   174		}),
   175		initial: "opening",
   176		on: {
   177			// Closing mid-save stops the in-flight invocation; its late result is
   178			// dropped. The write itself may still commit — the query client
   179			// reconciles the list either way.
   180			CLOSE: { target: ".closed" },
   181		},
   182		states: {
   183			opening: {
   184				always: [{ guard: "creating", target: "create" }, { target: "edit" }],
   185			},
   186			create: {
   187				initial: "drafting",
   188				states: {
   189					drafting: { on: { SAVE: { target: "saving", actions: "startSave" } } },
   190					saving: {
   191						tags: ["saving"],
   192						invoke: {
   193							src: "create",
   194							input: ({ context }) => {
   195								if (!context.draft) throw new Error("create needs a draft");
   196								return { body: createRequest(context.draft) };
   197							},
   198							onDone: {
   199								target: "#announcementSave.saved",
   200								actions: [{ type: "saved", params: ({ event }) => event.output }],
   201							},
   202							onError: {
   203								target: "failed",
   204								actions: assign({
   205									problem: ({ event }) => problemOf(event.error, "create"),
   206								}),
   207							},
   208						},
   209					},
   210					failed: { on: { SAVE: { target: "saving", actions: "startSave" } } },
   211				},
   212			},
   213			edit: {
   214				initial: "drafting",
   215				states: {
   216					drafting: {
   217						on: { SAVE: editSave },
   218					},
   219					savingSchedule: {
   220						tags: ["saving"],
   221						invoke: {
   222							src: "updateSchedule",
   223							input: ({ context }) => {
   224								const { id, draft } = requireBaseline(context);
   225								return { id, body: scheduleRequest(draft) };
   226							},
   227							onDone: {
   228								target: "savingCopy",
   229								actions: assign({
   230									baseline: ({ event }) => event.output.announcement,
   231									warnings: ({ event }) => event.output.warnings,
   232									scheduleApplied: true,
   233								}),
   234							},
   235							onError: {
   236								target: "scheduleFailed",
   237								actions: assign({
   238									problem: ({ event }) => problemOf(event.error, "schedule"),
   239								}),
   240							},
   241						},
   242					},
   243					savingCopy: {
   244						tags: ["saving"],
   245						invoke: {
   246							src: "updateCopy",
   247							input: ({ context }) => {
   248								const { id, draft } = requireBaseline(context);
   249								return { id, body: copyRequest(draft) };
   250							},
   251							onDone: {
   252								target: "#announcementSave.saved",
   253								actions: [
   254									{
   255										type: "saved",
   256										params: ({ context, event }) => ({
   257											announcement: event.output,
   258											warnings: context.warnings,
   259										}),
   260									},
   261								],
   262							},
   263							onError: {
   264								target: "copyFailed",
   265								actions: assign({
   266									problem: ({ event }) => problemOf(event.error, "copy"),
   267								}),
   268							},
   269						},
   270					},
   271					// Nothing was written; the next save starts from the opened row.
   272					scheduleFailed: {
   273						on: { SAVE: editSave },
   274					},
   275					// The schedule write (if any) committed and stays; only the copy
   276					// is missing. Retrying resumes at the copy stage unless the draft's
   277					// schedule changed again since that write.
   278					copyFailed: {
   279						on: { SAVE: editSave },
   280					},
   281				},
   282			},
   283			saved: { type: "final", entry: "close" },
   284			closed: { type: "final", entry: "close" },
   285		},
   286	});
   287	
   288	export type AnnouncementSaveSnapshot = SnapshotFrom<
   289		typeof announcementSaveMachine
   290	>;
